<?php

declare(strict_types=1);

namespace App\Api\Http;

use Symfony\Component\HttpFoundation\Request;

/**
 * The id of one API request, generated by the server (a client-supplied id is never trusted), echoed as X-Request-Id.
 */
final class ApiRequestId
{
    private const string ATTRIBUTE = '_api_request_id';

    private function __construct()
    {
    }

    public static function of(Request $request): string
    {
        $id = $request->attributes->get(self::ATTRIBUTE);
        if (!\is_string($id)) {
            $id = bin2hex(random_bytes(8));
            $request->attributes->set(self::ATTRIBUTE, $id);
        }

        return $id;
    }
}
